import ldapjs from 'ldapjs';
import { EventEmitter } from 'events';
import crypto from 'crypto';

interface PipelineContext {
  buildId: string;
  triggeredBy: string;
  branch: string;
  commitSha: string;
}

interface LDAPConfig {
  url: string;
  baseDN: string;
  bindDN: string;
  bindPassword: string;
}

class LDAPFilterBuilder {
  private components: string[] = [];

  addEquality(attr: string, value: string): this {
    this.components.push(`(${attr}=${this.sanitize(value)})`);
    return this;
  }

  addPresence(attr: string): this {
    this.components.push(`(${attr}=*)`);
    return this;
  }

  addSubstring(attr: string, value: string): this {
    this.components.push(`(${attr}=*${this.sanitize(value)}*)`);
    return this;
  }

  build(operator: '&' | '|' = '&'): string {
    if (this.components.length === 0) return '(objectClass=*)';
    if (this.components.length === 1) return this.components[0];
    return `(${operator}${this.components.join('')})`;
  }

  private sanitize(input: string): string {
    return input
      .replace(/\\/g, '\\5c')
      .replace(/\*/g, '\\2a')
      .replace(/\(/g, '\\28')
      .replace(/\)/g, '\\29')
      .replace(/\x00/g, '\\00');
  }
}

class PipelineAuthorizationCache {
  private cache = new Map<string, { groups: string[]; expiry: number }>();
  private pendingLookups = new Map<string, Promise<string[]>>();

  get(userId: string): string[] | null {
    const entry = this.cache.get(userId);
    if (entry && entry.expiry > Date.now()) {
      return entry.groups;
    }
    this.cache.delete(userId);
    return null;
  }

  set(userId: string, groups: string[]): void {
    this.cache.set(userId, { groups, expiry: Date.now() + 300000 });
  }

  getPending(userId: string): Promise<string[]> | null {
    return this.pendingLookups.get(userId) || null;
  }

  setPending(userId: string, promise: Promise<string[]>): void {
    this.pendingLookups.set(userId, promise);
  }

  clearPending(userId: string): void {
    this.pendingLookups.delete(userId);
  }
}

class CICDPipelineAuthorizer extends EventEmitter {
  private ldapConfig: LDAPConfig;
  private authCache: PipelineAuthorizationCache;
  private client: ldapjs.Client | null = null;

  constructor(config: LDAPConfig) {
    super();
    this.ldapConfig = config;
    this.authCache = new PipelineAuthorizationCache();
  }

  private async getClient(): Promise<ldapjs.Client> {
    if (this.client) return this.client;
    this.client = ldapjs.createClient({ url: this.ldapConfig.url });
    await new Promise<void>((resolve, reject) => {
      this.client!.bind(this.ldapConfig.bindDN, this.ldapConfig.bindPassword, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });
    return this.client;
  }

  private async resolveGroupMembership(userId: string): Promise<string[]> {
    const client = await this.getClient();
    const filterBuilder = new LDAPFilterBuilder();
    filterBuilder.addEquality('objectClass', 'groupOfNames');
    filterBuilder.addSubstring('member', userId);
    const filter = filterBuilder.build('&');

    return new Promise<string[]>((resolve, reject) => {
      const groups: string[] = [];
      client.search(this.ldapConfig.baseDN, { filter, scope: 'sub' }, (err, res) => {
        if (err) return reject(err);
        res.on('searchEntry', (entry) => {
          groups.push(entry.dn.toString());
        });
        res.on('end', () => resolve(groups));
        res.on('error', reject);
      });
    });
  }

  async getUserGroups(userId: string): Promise<string[]> {
    const cached = this.authCache.get(userId);
    if (cached) return cached;

    const pending = this.authCache.getPending(userId);
    if (pending) return pending;

    const lookupPromise = this.resolveGroupMembership(userId);
    this.authCache.setPending(userId, lookupPromise);

    try {
      const groups = await lookupPromise;
      this.authCache.set(userId, groups);
      return groups;
    } finally {
      this.authCache.clearPending(userId);
    }
  }

  async authorizePipelineExecution(context: PipelineContext): Promise<boolean> {
    const requiredGroup = `cn=pipeline-${context.branch},ou=ci-groups,${this.ldapConfig.baseDN}`;
    const groups = await this.getUserGroups(context.triggeredBy);
    return groups.some(g => g.toLowerCase() === requiredGroup.toLowerCase());
  }

  async resolveDeploymentApprovers(environment: string): Promise<string[]> {
    const client = await this.getClient();
    const filter = `(&(objectClass=person)(memberOf=cn=deploy-${environment},ou=approvers,${this.ldapConfig.baseDN}))`;

    return new Promise<string[]>((resolve, reject) => {
      const approvers: string[] = [];
      client.search(this.ldapConfig.baseDN, { filter, scope: 'sub' }, (err, res) => {
        if (err) return reject(err);
        res.on('searchEntry', (entry) => {
          approvers.push(entry.dn.toString());
        });
        res.on('end', () => resolve(approvers));
        res.on('error', reject);
      });
    });
  }

  async validateAndExecute(context: PipelineContext, environment: string): Promise<{ authorized: boolean; approvers?: string[] }> {
    const [authorized, approvers] = await Promise.all([
      this.authorizePipelineExecution(context),
      this.resolveDeploymentApprovers(environment)
    ]);

    this.emit('authorization-check', {
      buildId: context.buildId,
      user: context.triggeredBy,
      authorized,
      timestamp: new Date().toISOString()
    });

    return { authorized, approvers: authorized ? approvers : undefined };
  }
}

export { CICDPipelineAuthorizer, PipelineContext, LDAPConfig };
